// Paste your PaddleOCR API token between the quotes below.
// Use the token only. Do not include the word bearer.
const PADDLEOCR_TOKEN = '';

const token = String(PADDLEOCR_TOKEN || '').trim();
if (!token || token === 'PASTE_YOUR_PADDLEOCR_TOKEN_HERE') {
  throw new Error('Open the PaddleOCR Token Check node and replace PASTE_YOUR_PADDLEOCR_TOKEN_HERE with your PaddleOCR API token.');
}

return $input.all().map((item) => ({
  ...item,
  json: {
    ...item.json,
    paddleocrToken: token,
  },
}));

const items = $input.all();
const output = [];
const LF = String.fromCharCode(10);
const CR = String.fromCharCode(13);

for (const item of items) {
  const raw = item.json.jsonl ?? item.json.data ?? item.json.body ?? '';
  const lines = String(raw)
    .replaceAll(CR, '')
    .split(LF)
    .map((line) => line.trim())
    .filter(Boolean);

  const pages = [];
  const markdownImages = [];
  const outputImages = [];
  let pageNumber = 0;

  for (let lineIndex = 0; lineIndex < lines.length; lineIndex++) {
    let parsed;
    try {
      parsed = JSON.parse(lines[lineIndex]);
    } catch (error) {
      throw new Error(`Failed to parse PaddleOCR JSONL line ${lineIndex + 1}: ${error.message}`);
    }

    const layoutResults = parsed.result?.layoutParsingResults ?? [];
    for (const result of layoutResults) {
      const markdown = result.markdown ?? {};
      const markdownText = markdown.text ?? '';
      pages.push({
        page: pageNumber + 1,
        markdown: markdownText,
      });

      for (const [path, url] of Object.entries(markdown.images ?? {})) {
        markdownImages.push({ page: pageNumber + 1, path, url });
      }
      for (const [name, url] of Object.entries(result.outputImages ?? {})) {
        outputImages.push({ page: pageNumber + 1, name, url });
      }
      pageNumber++;
    }
  }

  const text = pages
    .map((page) => [`<!-- PaddleOCR page ${page.page} -->`, page.markdown].join(LF))
    .join(LF + LF);

  output.push({
    json: {
      text,
      pages,
      markdownImages,
      outputImages,
      paddleocr: {
        model: 'PaddleOCR-VL-1.6',
        jsonlLineCount: lines.length,
        pageCount: pages.length,
      },
    },
  });
}

return output;

const sourceFile = $('Google Drive').first().binary?.data?.fileName || $('Google Drive Trigger').first().json.name || 'uploaded.pdf';
if ($json.error) {
  throw new Error('DeepSeek extraction failed: ' + $json.error);
}

const extracted = ($json.output && typeof $json.output === 'object' && !Array.isArray($json.output))
  ? $json.output
  : $json;

const ocr = $('Parse PaddleOCR JSONL').first().json || {};
function asArray(value) {
  return Array.isArray(value) ? value : [];
}

function normalizeImage(image, source) {
  if (!image) return null;
  if (typeof image === 'string') {
    return { url: image, source, role: 'product_image', targetCell: 'B7' };
  }
  const url = image.url || image.imageUrl || image.image_url || image.href || image.dataUrl || image.data_url || '';
  if (!url) return null;
  return {
    ...image,
    url,
    source,
    role: image.role || 'product_image',
    targetCell: image.targetCell || 'B7',
  };
}

const deepseekImages = [
  ...asArray($json.product_images).map((image) => normalizeImage(image, 'deepseek')),
  ...asArray($json.output?.product_images).map((image) => normalizeImage(image, 'deepseek_output')),
].filter(Boolean);

// Prefer cropped images referenced from PaddleOCR markdown, e.g. imgs/img_in_image_box_*.jpg.
// layout_det_res images are page/layout previews, so use them only when no cropped image exists.
const markdownImages = asArray(ocr.markdownImages)
  .map((image) => normalizeImage(image, 'paddleocr_markdownImages'))
  .filter(Boolean);
const outputImages = asArray(ocr.outputImages)
  .map((image) => normalizeImage(image, 'paddleocr_outputImages'))
  .filter(Boolean);
const productImages = [
  ...deepseekImages,
  ...markdownImages,
  ...(markdownImages.length ? [] : outputImages),
].filter(Boolean);

const quote = {
  ...extracted,
  source_file: extracted.source_file || sourceFile,
  product_images: productImages,
  product_image_count: productImages.length,
};

const textFields = [
  'source_file', 'quote_date', 'order_no', 'supplier_name', 'supplier_contact',
  'supplier_phone', 'supplier_location', 'supplier_website', 'supplier_wechat',
  'product_name_en', 'size', 'materials', 'colors', 'logo', 'package', 'other',
  'mold_refund_condition', 'trade_term', 'payment_sample_mold', 'payment_bulk',
  'sample_fee', 'sample_time', 'transportation_cost', 'delivery_method', 'packing',
];
for (const key of textFields) {
  if (quote[key] === undefined || quote[key] === null || quote[key] === '') quote[key] = 'N/A';
}

for (const key of ['qty', 'unit_price_rmb', 'mold_fee_rmb', 'lead_time_days']) {
  const n = Number(String(quote[key] ?? '').replace(/[,RMB\s]/gi, ''));
  quote[key] = Number.isFinite(n) ? n : 0;
}

return [{
  json: {
    ...quote,
    quoteJsonBase64: Buffer.from(JSON.stringify(quote), 'utf8').toString('base64'),
  },
}];

const stdout = $json.stdout || '';
const jsonLine = stdout.split(/\r?\n/).map((line) => line.trim()).filter(Boolean).reverse().find((line) => line.startsWith('{'));
if (!jsonLine) {
  throw new Error('Excel generator did not return JSON. stdout=' + stdout + ' stderr=' + ($json.stderr || ''));
}
const result = JSON.parse(jsonLine);
const containerOutputPath = result.outputPath;

function todayInShanghai() {
  return new Intl.DateTimeFormat('en-CA', {
    timeZone: 'Asia/Shanghai',
    year: 'numeric',
    month: '2-digit',
    day: '2-digit',
  }).format(new Date()).replace(/-/g, '');
}

function normalizeDate(value) {
  const text = String(value || '').trim();
  if (!text || text.toUpperCase() === 'N/A') return todayInShanghai();
  const match = text.match(/(\d{4})[.\/\-?]?(\d{1,2})[.\/\-?]?(\d{1,2})/);
  if (!match) return todayInShanghai();
  const y = match[1];
  const m = match[2];
  const d = match[3];
  return y + m.padStart(2, '0') + d.padStart(2, '0');
}

function safeFilePart(value, fallback) {
  const raw = String(value || '').trim();
  if (!raw || raw.toUpperCase() === 'N/A') return fallback;
  const cleaned = raw
    .replace(/[<>:"/\\|?*\x00-\x1F]/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
  if (!cleaned || cleaned.toUpperCase() === 'N/A' || cleaned.toUpperCase() === 'N A') return fallback;
  return cleaned.slice(0, 90);
}

const quote = result.quote || {};
const productName = safeFilePart(quote.product_name_en, 'Quotation');
const datePart = normalizeDate(quote.quote_date);
const driveFileName = productName + '_' + datePart + '.xlsx';

return [{
  json: {
    ...result,
    containerOutputPath,
    driveFileName,
    driveFolderId: '1D7dud-WcTrHA1x4JuTwkjEdSvuDqyNtz',
    driveFolderUrl: 'https://drive.google.com/drive/folders/1D7dud-WcTrHA1x4JuTwkjEdSvuDqyNtz',
    message: 'Generated Excel: ' + containerOutputPath + '; Drive file name: ' + driveFileName,
  },
}];

// Manual mode: paste either a Google Drive PDF file ID or the full sharing URL.
// Supported examples:
//   1uOskHIT3WckE_Nc41k01EBcx6iFDuh8R
//   https://drive.google.com/file/d/1uOskHIT3WckE_Nc41k01EBcx6iFDuh8R/view?usp=drive_link
//   https://drive.google.com/open?id=1uOskHIT3WckE_Nc41k01EBcx6iFDuh8R
const MANUAL_GOOGLE_DRIVE_FILE = 'https://drive.google.com/file/d/1uOskHIT3WckE_Nc41k01EBcx6iFDuh8R/view?usp=drive_link';
const MANUAL_FILE_NAME = 'manual-input.pdf';

function extractDriveFileId(value) {
  const text = String(value || '').trim();
  if (!text || text === 'PASTE_GOOGLE_DRIVE_FILE_ID_HERE') return '';

  const patterns = [
    /\/file\/d\/([a-zA-Z0-9_-]+)/,
    /[?&]id=([a-zA-Z0-9_-]+)/,
    /\/d\/([a-zA-Z0-9_-]+)/,
  ];
  for (const pattern of patterns) {
    const match = text.match(pattern);
    if (match) return match[1];
  }

  return text.replace(/^['"]|['"]$/g, '').trim();
}

const id = extractDriveFileId(MANUAL_GOOGLE_DRIVE_FILE);
if (!id) {
  throw new Error('Open the Manual Input PDF File node and paste a Google Drive PDF file ID or sharing URL.');
}
if (/^https?:\/\//i.test(id)) {
  throw new Error('Could not extract a Google Drive file ID from the URL. Open the file link and copy the ID after /file/d/.');
}

return [{
  json: {
    id,
    name: MANUAL_FILE_NAME,
    mimeType: 'application/pdf',
    triggerMode: 'manual',
    manualInput: MANUAL_GOOGLE_DRIVE_FILE,
  },
}];
